fn main() {
    let mut sum = 0
    for d in range(1, 20) {
        for n in range(2, 20) {
            let mut factors = vec()
            for i in range(1, n) {
                if n % i == 0 {
                    factors = push(factors, i)
                }
            }
            let product = sum(factors)
            if product == n {
                sum = push(sum, n)
            }
        }
    }
    for n in sum {
        print(n)
        print_str("\n")
    }
}

struct Reading { label: Str, values: Vec<Int> }

fn first_big(v: Vec<Int>) -> Int {
    let found = -1
    for x in v {
        if x > 10 {
            found = x
            break
        }
    }
    found
}

fn second(v: Vec<Int>) -> Option<Int> {
    let x = get(v, 1)?
    Some(x + 1)
}

fn main() {
    let r = Reading { label: "lab", values: push(push(vec(), 3), 42) }
    print(first_big(r.values))            // field access copies: r stays usable
    let r2 = Reading { label: "lab2", ..r }
    match second(r2.values) {
        Some(n) => print(n),
        None => print_str("too short"),
    }
}

